/* IDO -O1 donor for game_libs_func_0006FC70 = libultra __osTimerInterrupt
 * (references/libreultra/src/os/timerintr.c, verbatim). PROVEN EXACT 94/94
 * standalone at BOTH IDO 7.1 -O1 and 5.3 -O1 (identical output; built with
 * 7.1). Same timerintr.o as game_libs_func_0006FBE4 (__osTimerServicesInit,
 * ends exactly at 0x6FC70 -- no inter-object pad here) and gl_func_0006FE5C
 * (__osInsertTimer). BOUNDARY FIXED 2026-09-09 (agent-g): the 2-word
 * "game_libs_func_0006FC70" (`lui t6; lw t6,0(t6)` = the hoisted
 * __osTimerList load, section 0x842DC = export sym 2638, jal'd from the
 * exception handler at 0x89878) is the real entry; the 0x170
 * "gl_func_0006FC78" was the rest of it (0x842E4 is NOT exported).
 * Reloc oracle inside the body: jal at +0xD4 -> sym 2640 (= 0x6FDE8,
 * __osSetTimerIntr), jal at +0x158 -> sym 2641 (= 0x6FE5C, __osInsertTimer).
 * Blank externs (USO load-time relocs, pins = 0): D_00000000_timerlist =
 * __osTimerList, gl_TimerCounter = __osTimerCounter (u32),
 * gl_func_00000000_count = osGetCount, _setcompare = __osSetCompare,
 * _sendmesg = osSendMesg, _settimerintr = __osSetTimerIntr,
 * _inserttimer = __osInsertTimer (the in-unit callees are named through
 * blank imports on purpose: a jal to the unit's own global symbol would
 * link as a baked address, while the USO word is blank + reloc).
 * Spliced into game_libs_post1b2c.c.o via REPLACE_FUNC_BODY. */
typedef unsigned int u32;
typedef unsigned long long OSTime;
typedef void *OSMesg;
typedef struct OSMesgQueue_s OSMesgQueue;

typedef struct OSTimer_s {
    /* 0x00 */ struct OSTimer_s *next;
    /* 0x04 */ struct OSTimer_s *prev;
    /* 0x08 */ OSTime interval;
    /* 0x10 */ OSTime value;
    /* 0x18 */ OSMesgQueue *mq;
    /* 0x1C */ OSMesg msg;
} OSTimer;
#define NULL 0
#define OS_MESG_NOBLOCK 0

extern OSTimer *D_00000000_timerlist;                       /* __osTimerList */
extern u32 gl_TimerCounter;                                 /* __osTimerCounter */
extern u32 gl_func_00000000_count(void);                    /* osGetCount */
extern void gl_func_00000000_setcompare(u32);               /* __osSetCompare */
extern int gl_func_00000000_sendmesg(OSMesgQueue *, OSMesg, int); /* osSendMesg */
extern void gl_func_00000000_settimerintr(OSTime);          /* __osSetTimerIntr (= gl_func_0006FDE8) */
extern OSTime gl_func_00000000_inserttimer(OSTimer *);      /* __osInsertTimer (= gl_func_0006FE5C) */

#define __osTimerList D_00000000_timerlist
#define __osTimerCounter gl_TimerCounter
#define osGetCount gl_func_00000000_count
#define __osSetCompare gl_func_00000000_setcompare
#define osSendMesg gl_func_00000000_sendmesg
#define __osSetTimerIntr gl_func_00000000_settimerintr
#define __osInsertTimer gl_func_00000000_inserttimer

void game_libs_func_0006FC70(void)
{
	OSTimer *t;
	u32 count;
	u32 elapsed_cycles;

	if (__osTimerList->next == __osTimerList)
		return;
	while (1)
	{
		t = __osTimerList->next;
		if (t == __osTimerList)
		{
			__osSetCompare(0);
			__osTimerCounter = 0;
			break;
		}
		count = osGetCount();
		elapsed_cycles = count - __osTimerCounter;
		__osTimerCounter = count;
		if (elapsed_cycles < t->value)
		{
			t->value -= elapsed_cycles;
			__osSetTimerIntr(t->value);
			return;
		}
		else
		{
			t->prev->next = t->next;
			t->next->prev = t->prev;
			t->next = NULL;
			t->prev = NULL;
			if (t->mq != NULL)
			{
				osSendMesg(t->mq, t->msg, OS_MESG_NOBLOCK);
			}
			if (t->interval != 0)
			{
				t->value = t->interval;
				__osInsertTimer(t);
			}
		}
	}
}

/* gl_func_0006FDE8 = libultra __osSetTimerIntr (same timerintr.c TU,
 * verbatim). PROVEN EXACT 29/29 at both 7.1 -O1 and 5.3 -O1. Section
 * 0x84454 = export sym 2640 (jal'd from __osTimerInterrupt +0xD4 and from
 * 0x87F48 = osSetTimer). Retires the "4-call cascade w/ 64-bit-add via
 * carry detect, 64-bit-stack-arg cap" NM decode: the 64-bit add is
 * `NewTime = tim + __osTimerCounter` (u64 + zero-extended u32, literal-0
 * high word + sltu carry), the "spilled-but-dead" high word is the
 * -O1 stack home of the u64 local, and the third call is
 * __osSetCompare((u32)NewTime) -- only the low word is an argument.
 * Blank externs: _disint = __osDisableInt, _resint = __osRestoreInt. */
extern u32 gl_func_00000000_disint(void);                   /* __osDisableInt */
extern void gl_func_00000000_resint(u32);                   /* __osRestoreInt */
#define __osDisableInt gl_func_00000000_disint
#define __osRestoreInt gl_func_00000000_resint

void gl_func_0006FDE8(OSTime tim)
{
	OSTime NewTime;
	u32 savedMask;
	savedMask = __osDisableInt();
	__osTimerCounter = osGetCount();
	NewTime = tim + __osTimerCounter;
	__osSetCompare(NewTime);
	__osRestoreInt(savedMask);
}
